import time
import logging
from collections import defaultdict
import numpy as np
import os

def generate_pod_level_link(pod_ij):
    print("debug pod_ij")
    np.set_printoptions(threshold=np.inf)
    print(pod_ij)
    C_pod = np.zeros((32, 32), dtype=int)
    from rapidAIsim.core.simulator import Simulator
    # Calculate the communication matrix at pod level
    for i in range(32):
        for j in range(32):
            if i == j:
                continue  
            C_pod[i][j] += pod_ij[i][j]

    from ortools.linear_solver import pywraplp
    solver = pywraplp.Solver.CreateSolver('Gurobi')
    c_ijt = np.empty((32, 32, 8), dtype=pywraplp.Variable)
    for i in range(32):
        for j in range(32):
            for t in range(8):
                c_ijt[i, j, t] = solver.IntVar(0, 16, f'c_{i}_{j}_{t}')
    obj_ij = np.empty((32, 32), dtype=pywraplp.Variable)
    for i in range(32):
        for j in range(32):
            obj_ij[i, j] = solver.IntVar(0, 128, f'obj_ij_{i}_{j}')
            
    for i in range(32):
        for j in range(32):
            solver.Add(obj_ij[i, j] >= solver.Sum(c_ijt[i, j, :].ravel().tolist()) - C_pod[i,j])
            solver.Add(obj_ij[i, j] >= C_pod[i,j] - solver.Sum(c_ijt[i, j, :].ravel().tolist()))
            
    for i in range(32):
        for t in range(8):
            solver.Add(solver.Sum(c_ijt[i, :, t].ravel().tolist()) <= 16) #leaf_spine_link_num
        
    for j in range(32):
        for t in range(8):
            solver.Add(solver.Sum(c_ijt[:, j, t].ravel().tolist()) <= 16)
        
    for i in range(32):
        for j in range(32):
            for t in range(8):
                solver.Add(c_ijt[i, j, t] == c_ijt[j, i, t] )

    obj = solver.Sum(obj_ij.ravel().tolist())
    solver.Minimize(obj)

    
    # 模型求解
    status = solver.Solve()
    if status != pywraplp.Solver.OPTIMAL and status != pywraplp.Solver.FEASIBLE:
        assert False
    # 获取结果
    def get_solution_variable(x):
        return x.solution_value()
    get_solution_variable = np.vectorize(get_solution_variable)
    init_C_ijt = get_solution_variable(c_ijt)
    print("start TE_solver")
    print(init_C_ijt)

